@@ -125,6 +125,11 @@ export async function proxy(req: NextRequest) {
     p.startsWith("/client/") ||
     rawLower === "/client" ||
     rawLower.startsWith("/client/");
+  const underPartners =
+    p === "/partners" ||
+    p.startsWith("/partners/") ||
