diff --git a/tests/proxy-partners.test.ts b/tests/proxy-partners.test.ts
new file mode 100644
index 00000000..951a22a2
--- /dev/null
+++ b/tests/proxy-partners.test.ts
@@ -0,0 +1,52 @@
+import { beforeAll, describe, expect, it } from "vitest";
+import { NextRequest } from "next/server";
+import { proxy } from "../proxy";
+import { CLIENT_COOKIE } from "../lib/client-auth-edge";
+
+// /partners sits behind the same check as /client: a signed client session
+// cookie. The positive control is load-bearing - a gate that redirected
+// everything would pass the negative assertions alone.
+
+const SECRET = "test-only-session-secret-not-used-in-prod-0123456789";
+
+async function mintClientCookie(slug: string, secret: string): Promise<string> {
+  const payload = btoa(JSON.stringify({ method: "client", slug, issuedAt: Date.now() }));
+  const key = await crypto.subtle.importKey(
+    "raw",
+    new TextEncoder().encode(secret),
+    { name: "HMAC", hash: "SHA-256" },
+    false,
+    ["sign"],
+  );
+  const mac = new Uint8Array(await crypto.subtle.sign("HMAC", key, new TextEncoder().encode(payload)));
+  const hex = Array.from(mac, (b) => b.toString(16).padStart(2, "0")).join("");
+  return `${payload}.${hex}`;
+}
+
+function reqFor(url: string, cookie?: string): NextRequest {
+  const headers = new Headers();
+  if (cookie) headers.set("cookie", `${CLIENT_COOKIE}=${cookie}`);
+  return new NextRequest(url, { headers });
+}
+
+function deniedToLogin(res: Response): boolean {
+  return (res.headers.get("location") || "").includes("/client/login");
+}
+
+beforeAll(() => {
+  process.env.SESSION_SECRET = SECRET;
+});
+
+describe("proxy() gate on /partners", () => {
+  it("denies without a valid client session and admits with one", async () => {
+    const url = "https://solaisoft.com/partners/deals";
+    expect(deniedToLogin(await proxy(reqFor(url)))).toBe(true);
+    expect(deniedToLogin(await proxy(reqFor("https://solaisoft.com/PARTNERS")))).toBe(true);
+    expect(deniedToLogin(await proxy(reqFor("https://solaisoft.com/x/..%2fpartners")))).toBe(true);
+    const forged = await mintClientCookie("station-street-fitness", "attacker-guessed-secret");
+    expect(deniedToLogin(await proxy(reqFor(url, forged)))).toBe(true);
+
+    const valid = await mintClientCookie("station-street-fitness", SECRET);
+    expect(deniedToLogin(await proxy(reqFor(url, valid)))).toBe(false);
+  });
+});
